args.query:
update api.company set name='ООО «Бета-Плюс»' where id=20008;
select table_schema,table_name,column_name from information_schema.columns where table_schema not in ('pg_catalog','information_schema') and data_type in ('text','character varying');
select * from api.limit_balance;

select 'app',number,description from api.application where description ilike '%Бета%' or verdict ilike '%Бета%';
select 'user',login,fio from api.app_user where fio ilike '%Бета%';
select 'contract',number from api.contract where status ilike '%Бета%' or number ilike '%Бета%';
